```ts
// 1 primitive
cy.wrap(18).should('be.a', 'number');

// 2 object
cy.wrap({ role: 'manager' }).its('role').should('eq', 'manager');

// 3 Promise
cy.wrap(Promise.resolve('ok')).should('eq', 'ok');

// 4 jQuery in each
cy.get('tr').each(($r) => { cy.wrap($r).should('be.visible'); });

// 5 custom command yield
Cypress.Commands.add('isoToday', () => cy.wrap('2026-09-16'));

// 6 after then
